34	impl MatchingWords {
35	    pub fn new(ctx: SearchContext<'_>, located_terms: Vec<LocatedQueryTerm>) -> Self {
36	        let mut phrases = Vec::new();
37	        let mut words = Vec::new();
38	
39	        // Extract and centralize the different phrases and words to match stored in a QueryTerm
40	        // and wrap them in dedicated structures.
41	        for located_term in located_terms {
42	            let term = ctx.term_interner.get(located_term.value);
43	            let (matching_words, matching_phrases) = term.all_computed_derivations();
44	
45	            for matching_phrase in matching_phrases {
46	                phrases.push(LocatedMatchingPhrase {
47	                    value: matching_phrase,
48	                    positions: located_term.positions.clone(),
49	                });
50	            }
51	
52	            words.push(LocatedMatchingWords {
53	                value: matching_words,
54	                positions: located_term.positions.clone(),
55	                is_prefix: term.is_prefix(),
56	                original_char_count: term.original_word(&ctx).chars().count(),
57	            });
58	        }
59	
60	        // Sort word to put prefixes at the bottom prioritizing the exact matches.
61	        words.sort_unstable_by_key(|lmw| (lmw.is_prefix, Reverse(lmw.positions.len())));
62	
63	        Self {
64	            phrases,
65	            words,
66	            word_interner: ctx.word_interner,
67	            phrase_interner: ctx.phrase_interner,
68	        }
69	    }
