77	    fn match_unique_words<'a>(&'a self, token: &Token<'_>) -> Option<MatchType<'a>> {
78	        for located_words in &self.words {
79	            for word in &located_words.value {
80	                let word = self.word_interner.get(*word);
81	                // if it is a stop-word, don't match
82	                if token.is_stopword() {
83	                    continue;
84	                }
85	                // if the word is a prefix, we match using starts_with.
