89	                    else {
90	                        continue;
91	                    };
92	                    let prefix_length = char_index + c.len_utf8();
93	                    let (char_count, byte_len) = token.original_lengths(prefix_length);
94	                    let ids = &located_words.positions;
95	                    return Some(MatchType::Full { ids, char_count, byte_len });
96	                // else we exact match the token.
